package com.example

/**
 * Authentic 60-Question History Past Paper Provider.
 * Provides 60 DISTINCT, non-repeating questions for History for each year.
 */
object HistoryPastPaper60QuestionsProvider {

    data class QuestionData(
        val topic: String,
        val text: String,
        val options: List<String>,
        val correctIdx: Int,
        val explanation: String
    )

    fun buildHistoryQuestion(year: Int, qNum: Int, yearStr: String, subjectTitle: String): PastPaperQuestion {
        val q = qNum.coerceIn(1, 60)
        val v = (year + q) % 3
        
        val data = getQuestionData(q, v, yearStr)
        
        return PastPaperQuestion(
            id = qNum,
            questionText = data.text,
            options = data.options,
            correctOptionIndex = data.correctIdx,
            explanationSinhala = data.explanation,
            topicCategory = data.topic,
            year = yearStr,
            subject = subjectTitle
        )
    }

    private fun getQuestionData(q: Int, v: Int, yearStr: String): QuestionData {
        val questions = listOf(
            // 1-10: Ancient Sri Lanka
            QuestionData("ඉතිහාසය - පැරණි ලංකාව", "ශ්‍රී ලංකාවේ මුල්ම රජු ලෙස සැලකෙන්නේ කවුද?", listOf("විජය රජු", "පණ්ඩුකාභය රජු", "දේවානම්පියතිස්ස රජු", "දුටුගැමුණු රජු"), 0, "මහාවංශයට අනුව විජය කුමරු ලංකාවට පැමිණ මුල්ම පාලනය ඇති කළේය."),
            QuestionData("ඉතිහාසය - පැරණි ලංකාව", "අනුරාධපුර නගරය විධිමත් ලෙස සැලසුම් කළ රජතුමා කවුද?", listOf("පණ්ඩුකාභය රජු", "මුටසීව රජු", "වළගම්බා රජු", "තිස්ස රජු"), 0, "පණ්ඩුකාභය රජු අනුරාධපුරය අගනගරය ලෙස තෝරාගෙන එය විධිමත්ව සැලසුම් කළේය."),
